SELECT p.slug project,l.root_path,d.path,d.document_kind,d.title,CASE WHEN c.search_vector @@ websearch_to_tsquery('simple',$1) THEN ts_headline('simple',c.content,websearch_to_tsquery('simple',$1),'MaxWords=100,MinWords=20,MaxFragments=2,StartSel=<<,StopSel=>>,FragmentDelimiter= ... ') ELSE left(c.content,700) END excerpt,d.last_seen_at::text,d.freshness_status,CASE WHEN c.search_vector @@ websearch_to_tsquery('simple',$1) THEN 'full-text match; ' ELSE 'path match; ' END || 'freshness=' || d.freshness_status reason,ts_rank(c.search_vector,websearch_to_tsquery('simple',$1)) score FROM document_chunks c JOIN document_revisions v ON v.id=c.document_revision_id AND v.is_current JOIN source_documents d ON d.id=v.source_document_id JOIN repository_locations l ON l.id=d.repository_location_id JOIN projects p ON p.id=d.project_id WHERE ($2::text IS NULL OR p.slug=$2) AND ($3::text IS NULL OR d.freshness_status=$3) AND EXISTS (SELECT 1 FROM unnest($5::text[]) AS allowed(root_path) WHERE l.root_path=allowed.root_path) AND (c.search_vector @@ websearch_to_tsquery('simple',$1) OR d.path ILIKE '%' || $1 || '%') ORDER BY (d.freshness_status='current') DESC,score DESC,d.last_seen_at DESC LIMIT $4
